#include <iostream>
#include "vector_curve_sampler.h"
int main(){try{unsigned checks=0;auto verify=[&](std::array<float,3>a,std::array<float,3>b){if(a!=b)throw std::runtime_error("vector curve mismatch");++checks;};RecoveredVectorCurveSampler s;s.times={10000,30000};s.values={{{2,4,6}},{{6,8,10}}};s.info.defaultKind=6*257;verify(s.sample(20000),{4,6,8});verify(s.sample(5000),{1,2,3});verify(s.sample(40000),{6,8,10});verify(s.sample(20000),{4,6,8});s.info.rightEdgeTime=50000;s.info.useEdgeInfo=true;s.info.rightActive=true;s.info.rightValue={10,12,14};verify(s.sample(40000),{8,10,12});verify(s.sample(60000),{});s.kinds={15,6<<8};verify(s.sample(20000),{2,4,6});s.kinds={6,15<<8};verify(s.sample(20000),{6,8,10});s.kinds={15,15<<8};verify(s.sample(20000),{2,4,6});RecoveredVectorCurveSampler empty;empty.info.rightEdgeTime=20000;empty.info.defaultKind=6*257;empty.info.useEdgeInfo=true;empty.info.leftActive=empty.info.rightActive=true;empty.info.leftValue={2,4,6};empty.info.rightValue={6,8,10};verify(empty.sample(10000),{4,6,8});verify(empty.sample(30000),{});empty.info.rightEdgeTime=0;bool rejected=false;try{empty.sample(0);}catch(const std::runtime_error&){rejected=true;}if(!rejected)throw std::runtime_error("unsupported empty accepted");++checks;std::cout<<"vector_curve_sampler_checks="<<checks<<'\n';return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
